 public async void RunMediaChecks(bool live=false){string output=Path.GetFullPath(Path.Combine(baseDir,live?"../test-output/media-live.txt":"../test-output/media.txt"));int checks=0;Action<bool,string> check=(ok,message)=>{checks++;if(!ok)throw new Exception(message);};try{
  timer.Stop();audio.Dispose();Profile=new Profile{Name="Player"};Profile.Settings.Music=false;Profile.Settings.Sound=false;Profile.Settings.Volume=0;audio=new AudioSystem(Profile.Settings);page="home";Build();
  foreach(string url in new[]{"https://youtu.be/BaW_jenozKc","https://www.youtube.com/watch?v=BaW_jenozKc","https://music.youtube.com/watch?v=test","https://www.tiktok.com/music/test-123","https://vm.tiktok.com/test/"})check(MusicImportService.ValidLink(url),"Valid media URL rejected");
  foreach(string url in new[]{"file:///C:/test","http://youtube.com/watch?v=x","https://youtube.com.evil.example/test","https://user:pass@youtube.com/test","https://127.0.0.1/test","https://youtube.com:123/test","not a link"})check(!MusicImportService.ValidLink(url),"Invalid media URL accepted");
  ImportMusicFiles(new[]{Path.Combine(baseDir,"assets/click.wav"),Path.Combine(baseDir,"assets/wrong.wav")});check(Profile.Settings.CustomMusic.Count==2&&audio.Tracks.Count==5,"Multiple-file import failed");CloseModal();var track=audio.AllTracks.Last();string filename=AudioSystem.Resolve(track.File),hash=UpdateFiles.Hash(filename);audio.RenameTrack(track.File,"My music name");check(audio.AllTracks.Last().Title=="My music name"&&UpdateFiles.Hash(filename)==hash,"Rename changed the file");Save();var reload=store.Load();check(reload.Settings.MusicTitles[track.File]=="My music name","Display name was not saved");reload.Settings.Music=false;using(var restored=new AudioSystem(reload.Settings))check(restored.AllTracks.Last().Title=="My music name","Display name not restored");RadioSelection();UpdateLayout();await System.Threading.Tasks.Task.Delay(40);check(Descendants<Button>(overlay).Count(b=>Convert.ToString(b.Content)=="✎")==2,"Imported tracks missing rename buttons");ImportMusicLink();check(Descendants<TextBox>(overlay).Single().MaxLength==2048&&Descendants<Button>(overlay).Any(b=>Convert.ToString(b.Content)=="Paste"),"Link input/paste missing");Capture("public-music-import");CloseModal();
  int before=Directory.GetDirectories(Path.Combine(AppPaths.DataDirectory,"music")).Length;using(var service=new MusicImportService())using(var cancel=new CancellationTokenSource()){var task=service.DownloadAsync("https://www.youtube.com/watch?v=BaW_jenozKc",null,cancel.Token);int pid=service.WorkerId;check(pid>0,"Downloader did not start");cancel.Cancel();try{await task;throw new Exception("Cancelled import completed");}catch(OperationCanceledException){}try{using(var process=System.Diagnostics.Process.GetProcessById(pid))check(process.HasExited,"Downloader survived cancellation");}catch(ArgumentException){checks++;}}
  check(Directory.GetDirectories(Path.Combine(AppPaths.DataDirectory,"music")).Length==before,"Cancelled import left a partial folder");
  if(live){foreach(string url in new[]{"https://www.youtube.com/watch?v=jNQXAC9IVRw","https://www.tiktok.com/music/original-sound-7688400273810737951","https://www.tiktok.com/@cookierun_dev/video/7039716639834656002"})using(var service=new MusicImportService()){var result=await service.DownloadAsync(url,null,CancellationToken.None);check(File.Exists(result.File)&&new FileInfo(result.File).Length>512&&result.File.EndsWith(".mp3"),"Live import did not produce MP3");string relative="data"+Path.DirectorySeparatorChar+result.File.Substring(AppPaths.DataDirectory.Length+1);audio.AddTrack(relative);audio.RenameTrack(relative,result.Title);check(audio.AllTracks.Last().Title==result.Title,"Live import lost the source title");}Save();}
  audio.Select(0);Profile.Settings.Music=false;audio.ApplyVolume();game=null;page="home";selectedTopic="mixed";Profile.Settings.Difficulty=3;Build();Capture("public-home");game=new GameSession(1){Topic="english",Questions=new System.Collections.Generic.List<Question>{bank.Questions.First(q=>q.Kind=="order"&&q.Difficulty==1)}};page="game";interactionId="";Build();Capture("public-gameplay");game=null;page="notebook";Profile.Notebook=new System.Collections.Generic.List<NotebookPage>{new NotebookPage{Template="rabbit-body"}};Profile.NotebookIndex=0;Build();Capture("public-notebook");
  File.WriteAllText(output,"PASS: "+checks+" media checks (live="+live+"). Batch import copies multiple files, display-only names persist without changing file bytes, imported tracks have rename controls, link/paste UI, strict supported-link validation, real downloader cancellation/process termination and partial-folder cleanup. Public screenshots rendered without desktop automation.");
 }catch(Exception error){File.WriteAllText(output,"FAIL: "+error);Environment.ExitCode=1;}finally{game=null;closing=true;Close();}}
